      const {
        root,
        node: { codegenNode }
      } = parseWithIfTransform(`<div v-if="ok"/><p v-else/>`)
      assertSharedCodegen(codegenNode)
      const branch1 = (codegenNode.expressions[1] as ConditionalExpression)
        .consequent as CallExpression
