    const existingProps = vnodeCall.arguments[propsIndex] as
      | PropsExpression
      | undefined
      | 'null'
    vnodeCall.arguments[propsIndex] = injectProp(
      existingProps,
      keyProperty,
      context
    )
    return childCodegen
  }
}

