  PropNames extends string,
  RawBindings,
  D,
  C extends ComputedOptions = {},
  M extends MethodOptions = {}
>(
  options: ComponentOptionsWithArrayProps<PropNames, RawBindings, D, C, M>
): {
  new (): ComponentPublicInstance<
    { [key in PropNames]?: unknown },
    RawBindings,
    D,
    C,
    M
  >
}

