import { VNodeChild } from '../vnode'
import { isArray, isString, isObject } from '@vue/shared'

export function renderList(
  source: any,
  renderItem: (value: any, key: string | number, index?: number) => VNodeChild
): VNodeChild[] {
  let ret: VNodeChild[] = []
  if (isArray(source) || isString(source)) {
    for (let i = 0, l = source.length; i < l; i++) {
      ret.push(renderItem(source[i], i))
    }
  } else if (typeof source === 'number') {
    for (let i = 0; i < source; i++) {
      ret.push(renderItem(i + 1, i))
    }
  } else if (isObject(source)) {
    if (source[Symbol.iterator as any]) {
      ret = []
      const iterator: Iterator<any> = source[Symbol.iterator as any]()
      let result = iterator.next()
      while (!result.done) {
        ret.push(renderItem(result.value, ret.length))
        result = iterator.next()
      }
    } else {
      const keys = Object.keys(source)
      ret = new Array(keys.length)
      for (let i = 0, l = keys.length; i < l; i++) {
        const key = keys[i]
        ret[i] = renderItem(source[key], key, i)
      }
    }
  }
  return ret
}

import { Slot } from '../componentSlots'
import {
  VNodeChildren,
  openBlock,
  createBlock,
  Fragment,
  VNode
} from '../vnode'
import { PatchFlags } from '@vue/shared'

export function renderSlot(
  slots: Record<string, Slot>,
  name: string,
  props: any = {},
  // this is not a user-facing function, so the fallback is always generated by
  // the compiler and gurunteed to be an array
  fallback?: VNodeChildren
): VNode {
  const slot = slots[name]
  return (
    openBlock(),
    createBlock(
      Fragment,
      { key: props.key },
      slot ? slot(props) : fallback || [],
      slots._compiled ? 0 : PatchFlags.BAIL
    )
  )
}

